Select p21_view_check_line.linexxxdef,p21_view_check_line.invoice_no,p21_view_check_line.voucher_no,p21_view_check_line.header_number,p21_view_check_line.check_no,p21_view_check_line.check_amount_display,p21_view_check_line.terms_taken_amount_display,p21_view_check_line.invoice_date,p21_view_check_line.description,p21_view_check_line.terms_amount_taken,p21_view_check_line.amount_paid,p21_view_check_line.ap_amount,p21_view_check_line.vendor_id,p21_view_check_line.vendor_name,p21_view_check_line.used_in_us,voucher_line_detail.disputed_amt,( p21_view_check_line.amount_paid + voucher_line_detail.disputed_amt ) AS adjusted_amt,p21_view_check_line.iva_paid_reduced,p21_view_check_line.iva_withheld/*MAIN FROM CLAUSE*/From p21_view_check_line/*NESTED SELECT BEGIN*/INNER JOIN ( SELECT apinv_line.voucher_no AS voucher_no, sum(disputed_amt) AS disputed_amt FROM apinv_line GROUP BY apinv_line.voucher_no ) AS voucher_line_detail ON ( voucher_line_detail.voucher_no = p21_view_check_line.voucher_no )/*NESTED SELECT END*//*MAIN WHERE CLAUSE*/WHERE ( p21_view_check_line.company_number = '1') and( p21_view_check_line.bank_number = 13 ) and( p21_view_check_line.currency_id = 1) and ( p21_view_check_line.check_no >= '001277' and p21_view_check_line.check_no <= '001277' ) AND( 'Y' = 'N' OR edi_check = 'N' )AND p21_view_check_line.eft = 'N'